  public static void saveLogList()
  {
    if (MarbleColorSettings.SavingLog | MarbleColorSettings.CheckingLogSize)
      return;
    MarbleColorSettings.SavingLog = true;
    if (MarbleMotionCommands.LogList != null)
    {
      TextWriter textWriter1 = (TextWriter) System.IO.File.AppendText(Application.StartupPath + "\\buMarbleLog5.csv");
      for (int index = 0; index <= MarbleMotionCommands.LogList.Count - 1; ++index)
        textWriter1.Write(MarbleMotionCommands.LogList[index]);
      textWriter1.Close();
      TextWriter textWriter2 = (TextWriter) System.IO.File.AppendText(Application.StartupPath + "\\buMarbleInstantLog5.csv");
      for (int index = 0; index <= MarbleMotionCommands.LogList.Count - 1; ++index)
        textWriter2.Write(MarbleMotionCommands.LogList[index]);
      textWriter2.Close();
      MarbleMotionCommands.LogList.Clear();
    }
    MarbleColorSettings.SavingLog = false;
  }

